    if (!commit || value === ed.old) {
      ed.td.innerHTML = ed.html;
      return ed.td;
    }
    ed.td.innerHTML = "";
    $("<span>").text(value).appendTo(ed.td);
    ed.td.setAttribute("data-value", value);
    var key = ed.tr.getAttribute("data-key");
    ed.td.setAttribute("data-key", key);
